probes.pf:
local R = _G.DPC_dbg and _G.DPC_dbg.R
if not R or not R.pf then return "no DPC dev" end
local parts = {}
for k, n in pairs(R.pf.n) do parts[#parts + 1] = k .. "=" .. n end
table.sort(parts)
return table.concat(parts, " ") .. (R.pf.voice_err and (" ERR " .. R.pf.voice_err) or "") .. (R.pf.listener_err and (" ERR " .. R.pf.listener_err) or "")
